void ass_add_font(ASS_Library *priv, char *name, char *data, int size) /* <=== ass_add_font */ 
{
    int idx = priv->num_fontdata;
    if (!name || !data || !size)
        return;
    if (!grow_array((void **) &priv->fontdata, priv->num_fontdata,
                    sizeof(*priv->fontdata)))
        return;

    priv->fontdata[idx].name = strdup(name);
    priv->fontdata[idx].data = malloc(size);

    if (!priv->fontdata[idx].name || !priv->fontdata[idx].data)
        goto error;

    memcpy(priv->fontdata[idx].data, data, size);

    priv->fontdata[idx].size = size;

    priv->num_fontdata++;
    return;

error:
    free(priv->fontdata[idx].name);
    free(priv->fontdata[idx].data);
}

static unsigned char *decode_chars(const unsigned char *src, /* <=== decode_chars */ 
                                   unsigned char *dst, size_t cnt_in)
{
    uint32_t value = 0;
    for (int i = 0; i < cnt_in; i++)
        value |= (uint32_t) ((src[i] - 33u) & 63) << 6 * (3 - i);

    *dst++ = value >> 16;
    if (cnt_in >= 3)
        *dst++ = value >> 8 & 0xff;
    if (cnt_in >= 4)
        *dst++ = value & 0xff;
    return dst;
}

static int grow_array(void **array, int nelem, size_t elsize) /* <=== grow_array */ 
{
    if (!(nelem & 31)) {
        void *ptr = realloc(*array, (nelem + 32) * elsize);
        if (!ptr)
            return 0;
        *array = ptr;
    }
    return 1;
}

